func (r *mutationResolver) OverLayUpload(ctx context.Context, files []*model.UploadFile) ([]*model.File, error) {
	// var images []image.Image

	// Configure Redis
	rdb := redis.ConfigureRedis()

	for i, file := range files {
		// Use the ReadSeeker interface
		f := file.File.File

		// Convert image to byte slice
		byteSlice, err := redis.ImageToByteSlice(f)
		if err != nil {
			return nil, fmt.Errorf(" Error converting image to byte slice: %v", err)
		}

		// Store byte slice in Redis
		key := fmt.Sprintf("image_key_%d", i)
		err = redis.PassByteSliceToRedis(rdb, key, byteSlice)
		if err != nil {
			return nil, fmt.Errorf(" Error storing byte slice in Redis: %v", err)
		}
	}

	// Retrieve images from Redis and save locally
	outputDir := "./uploaded_images"
	if _, err := os.Stat(outputDir); !os.IsNotExist(err) {
		if err := os.RemoveAll(outputDir); err != nil {
			return nil, fmt.Errorf("could not remove existing output directory: %v", err)
		}
	}
	if err := os.MkdirAll(outputDir, os.ModePerm); err != nil {
		return nil, fmt.Errorf("could not create output directory: %v", err)
	}

	for i := range files {
		key := fmt.Sprintf("image_key_%d", i)
		retrievedByteSlice, err := redis.RetrieveByteSliceFromRedis(rdb, key)
		if err != nil {
			return nil, fmt.Errorf(" Error retrieving byte slice from Redis: %v", err)
		}

		outputImage, err := redis.ByteSliceToImage(retrievedByteSlice)
		if err != nil {
			return nil, fmt.Errorf(" Error converting byte slice to image: %v", err)
		}

		// images = append(images, outputImage)

		// Save the image locally
		outputPath := filepath.Join(outputDir, fmt.Sprintf("image_%d.png", i))
		file, err := os.Create(outputPath)
		if err != nil {
			return nil, fmt.Errorf("could not create image file: %v", err)
		}
		defer file.Close()

		err = png.Encode(file, outputImage)
		if err != nil {
			return nil, fmt.Errorf("could not encode image to PNG: %v", err)
		}
	}

	// FFmpeg command to create video from images
	outputVideoPath := "./output/slideshow.mp4"
	ffmpegCmd := exec.Command("ffmpeg",
		"-framerate", "1/5", // 1 image every 5 seconds
		"-pattern_type", "glob", // Use glob pattern for input file
		"-i", filepath.Join(outputDir, "*.png"), // Input images
		"-vf", "scale=972:768", // Scale the video
		"-c:v", "libx264", // Video codec
		"-pix_fmt", "yuv420p", // Pixel format
		outputVideoPath) // Output file path

	output, err := ffmpegCmd.CombinedOutput()
	if err != nil {
		return nil, fmt.Errorf("ffmpeg error: %v, output: %s", err, output)
	}

	return []*model.File{{Name: "slideshow.mp4", Content: outputVideoPath}}, nil
}

func (r *mutationResolver) SingleUpload(ctx context.Context, bgFiles []*graphql.Upload, overlayFiles []*graphql.Upload) (*model.ImageFiles, error) {
	rdb := redis.ConfigureRedis()
	fmt.Printf("Redis client: %v\n", rdb)

	// Helper function to process and store images in Redis
	processAndStoreImages := func(files []*graphql.Upload, prefix string) ([]string, error) {
		var imageKeys []string
		for _, file := range files {
			buf := new(bytes.Buffer)
			if _, err := io.Copy(buf, file.File); err != nil {
				return nil, fmt.Errorf("error reading file: %w", err)
			}

			uniqueID := uuid.New().String()
			imageKey := fmt.Sprintf("%s_image_key_%s", prefix, uniqueID)
			if err := redis.PassByteSliceToRedis(rdb, imageKey, buf.Bytes()); err != nil {
				return nil, fmt.Errorf("error storing byte slice in Redis: %w", err)
			}
			imageKeys = append(imageKeys, imageKey)
		}
		return imageKeys, nil
	}

	var wg sync.WaitGroup
	var bgImageKeys, overlayImageKeys []string
	var bgErr, overlayErr error

	wg.Add(2)
	go func() {
		defer wg.Done()
		bgImageKeys, bgErr = processAndStoreImages(bgFiles, "bg")
		if bgErr != nil {
			log.Printf("Error processing background images: %v", bgErr)
		}
	}()
	go func() {
		defer wg.Done()
		overlayImageKeys, overlayErr = processAndStoreImages(overlayFiles, "overlay")
		if overlayErr != nil {
			log.Printf("Error processing overlay images: %v", overlayErr)
		}
	}()
	wg.Wait()

	if bgErr != nil {
		return nil, fmt.Errorf("error processing background images: %w", bgErr)
	}
	if overlayErr != nil {
		return nil, fmt.Errorf("error processing overlay images: %w", overlayErr)
	}

	var ffmpegWg sync.WaitGroup
	var bgOutputBytes, overlayOutputBytes []byte
	var bgFfmpegErr, overlayFfmpegErr error

	ffmpegWg.Add(2)
	go func() {
		defer ffmpegWg.Done()
		bgOutputBytes, bgFfmpegErr = redis.PassImagesToFfmpeg_BG_Bytes(bgImageKeys, rdb, "scale=-1:1920")
		if bgFfmpegErr != nil {
			log.Printf("Error creating background video: %v", bgFfmpegErr)
		}
	}()
	go func() {
		defer ffmpegWg.Done()
		overlayOutputBytes, overlayFfmpegErr = redis.PassImagesToFfmpeg_OVERLAY_Bytes(overlayImageKeys, rdb, "scale=972:768")
		if overlayFfmpegErr != nil {
			log.Printf("Error creating overlay video: %v", overlayFfmpegErr)
		}
	}()
	ffmpegWg.Wait()

	if bgFfmpegErr != nil {
		return nil, fmt.Errorf("error creating background video: %w", bgFfmpegErr)
	}
	if overlayFfmpegErr != nil {
		return nil, fmt.Errorf("error creating overlay video: %w", overlayFfmpegErr)
	}

	combinedVideo, err := redis.CombineVideosFromMemory(bgOutputBytes, overlayOutputBytes, "mp4", 54, 210)
	if err != nil {
		return nil, fmt.Errorf("error combining videos: %w", err)
	}

	combinedBase64 := base64.StdEncoding.EncodeToString(combinedVideo)
	// fmt.Printf("combinedBase64 msm: %v\n", combinedBase64)

	bgBase64 := base64.StdEncoding.EncodeToString(bgOutputBytes)
	overlayBase64 := base64.StdEncoding.EncodeToString(overlayOutputBytes)

	return &model.ImageFiles{
		Overlay: overlayBase64,
		Bg:      bgBase64,
		Combine: &combinedBase64,
	}, nil
}

func (r *mutationResolver) AdvertisementUpload(ctx context.Context, bgFiles []*graphql.Upload, productID string) (*model.ImageFiles, error) {
	rdb := redis.ConfigureRedis()

	var product model.Product
	if err := r.DB.Where("id = ?", productID).Find(&product).Error; err != nil {
		return nil, err
	}

	processAndStoreImages := func(files []*graphql.Upload, prefix string, ch chan<- []string) {
		var imageKeys []string
		for _, file := range files {
			buf := new(bytes.Buffer)
			if _, err := io.Copy(buf, file.File); err != nil {
				log.Printf("Error reading file: %v", err)
				ch <- nil
				return
			}

			uniqueID := uuid.New().String()
			imageKey := fmt.Sprintf("%s_image_key_%s", prefix, uniqueID)
			if err := redis.PassByteSliceToRedis(rdb, imageKey, buf.Bytes()); err != nil {
				log.Printf("Error storing byte slice in Redis: %v", err)
				ch <- nil
				return
			}
			imageKeys = append(imageKeys, imageKey)
		}
		ch <- imageKeys
	}

	processAndStoreMinIOImages := func(imageUrls []string, prefix string, ch chan<- []string) {
		var imageKeys []string
		for _, url := range imageUrls {
			imageData, err := helper.ImageFromMinIOURL(ctx, r.MinIOClient, url)
			if err != nil {
				log.Printf("Error retrieving image data from MinIO: %v", err)
				ch <- nil
				return
			}

			uniqueID := uuid.New().String()
			imageKey := fmt.Sprintf("%s_image_key_%s", prefix, uniqueID)
			if err := redis.PassByteSliceToRedis(rdb, imageKey, imageData); err != nil {
				log.Printf("Error storing byte slice in Redis: %v", err)
				ch <- nil
				return
			}
			imageKeys = append(imageKeys, imageKey)
		}
		ch <- imageKeys
	}

	bgCh := make(chan []string)
	overlayCh := make(chan []string)

	go processAndStoreImages(bgFiles, "bg", bgCh)
	go processAndStoreMinIOImages(product.ImageUrls, "overlay", overlayCh)

	bgImageKeys := <-bgCh
	overlayImageKeys := <-overlayCh

	if bgImageKeys == nil || overlayImageKeys == nil {
		return nil, fmt.Errorf("error processing images")
	}

	var ffmpegWg sync.WaitGroup
	var bgOutputBytes, overlayOutputBytes []byte
	var bgFfmpegErr, overlayFfmpegErr error

	ffmpegWg.Add(2)
	go func() {
		defer ffmpegWg.Done()
		bgOutputBytes, bgFfmpegErr = redis.PassImagesToFfmpeg_BG_Bytes(bgImageKeys, rdb, "scale=-1:1920")
	}()
	go func() {
		defer ffmpegWg.Done()
		overlayOutputBytes, overlayFfmpegErr = redis.PassImagesToFfmpeg_OVERLAY_Bytes(overlayImageKeys, rdb, "scale=972:768")
	}()
	ffmpegWg.Wait()

	if bgFfmpegErr != nil || overlayFfmpegErr != nil {
		return nil, fmt.Errorf("error creating videos")
	}

	// 	X 185.625
	// sidesheet.tsx:143 Y 382.79999999999995

	combinedVideo, err := redis.CombineVideosFromMemory(bgOutputBytes, overlayOutputBytes, "mp4", 54, 210)
	if err != nil {
		return nil, fmt.Errorf("error combining videos: %w", err)
	}

	combinedBase64 := base64.StdEncoding.EncodeToString(combinedVideo)
	bgBase64 := base64.StdEncoding.EncodeToString(bgOutputBytes)
	overlayBase64 := base64.StdEncoding.EncodeToString(overlayOutputBytes)

	return &model.ImageFiles{
		Overlay: overlayBase64,
		Bg:      bgBase64,
		Combine: &combinedBase64,
	}, nil
}

func (r *mutationResolver) CombineUpload(ctx context.Context, input *string) (*string, error) {
	overlayVideoPath := "helper/overlay_video.mp4"
	backgroundVideoPath := "helper/background_video.mp4"

	// Read the background video into bytes
	backgroundVideoBytes, err := os.ReadFile(backgroundVideoPath)
	if err != nil {
		return nil, fmt.Errorf("failed to read background video: %v", err)
	}

	// Read the overlay video into bytes
	overlayVideoBytes, err := os.ReadFile(overlayVideoPath)
	if err != nil {
		return nil, fmt.Errorf("failed to read overlay video: %v", err)
	}
	combinedVideo, err := redis.CombineVideosFromMemory(backgroundVideoBytes, overlayVideoBytes, "mp4", 54, 210)
	if err != nil {
		return nil, fmt.Errorf("error combining videos: %w", err)
	}

	combinedBase64 := base64.StdEncoding.EncodeToString(combinedVideo)
	fmt.Printf("combinedBase64 msm: %v\n", combinedBase64)

	return &combinedBase64, nil
}

func (r *queryResolver) ImageUrls(ctx context.Context) ([]string, error) {
	// Retrieve the VendorID from the context
	VendorIDStr, err := r.GetID(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get vendor ID: %v", err)
	}

	// Convert VendorID from string to uuid.UUID
	VendorID, err := uuid.Parse(*VendorIDStr)
	if err != nil {
		return nil, fmt.Errorf("invalid vendor ID format: %v", err)
	}

	bucketName := fmt.Sprintf("vendor-%s-bucket", VendorID)
	// List objects in the bucket
	objectCh := r.MinIOClient.ListObjects(ctx, bucketName, minio.ListObjectsOptions{Recursive: true})

	var urls []string
	for object := range objectCh {
		if object.Err != nil {
			return nil, object.Err
		}
		fileURL := fmt.Sprintf("http://%s/%s/%s", os.Getenv("MINIO_ENDPOINT"), bucketName, object.Key)
		urls = append(urls, fileURL)
	}

	return urls, nil
}

